The baseline is a linear recurrence, so each T_k waits on the previous one and the depth reaches 8. I rebuild T2..T7 with product identities, T_m·T_n = (T_{m+n} + T_{|m−n|})/2:

- T2 = 2z² − 1
- T3 = 2z·T2 − z
- T4 = 2T2² − 1
- T5 = 2T2·T3 − z
- T6 = 2T3² − 1
- T7 = 2T3·T4 − z

The doublings are done with additions, so the multiplication count stays at 6 ciphertext-ciphertext products, but the depth drops to about 4 before the coefficient multiplies, giving 5 levels in total instead of 8. The 2× factors are plain additions, not constant multiplies, which respects the CKKS rules.

```cpp
void fhe()
{
  Ciphertext x("x");
  Plaintext alpha("alpha");
  Plaintext one("one");

  // z = x/4 in [-1, 1]  (depth 1)
  Ciphertext z = x * alpha;

  // T2 = 2 z^2 - 1  (depth 2)
  Ciphertext z2 = z * z;
  Ciphertext t2 = z2 + z2 - one;

  // T3 = 2 z T2 - z  (depth 3)
  Ciphertext zt2 = z * t2;
  Ciphertext t3 = zt2 + zt2 - z;

  // T4 = 2 T2^2 - 1  (depth 3)
  Ciphertext t2sq = t2 * t2;
  Ciphertext t4 = t2sq + t2sq - one;

  // T5 = 2 T2 T3 - z  (depth 4)
  Ciphertext t2t3 = t2 * t3;
  Ciphertext t5 = t2t3 + t2t3 - z;

  // T6 = 2 T3^2 - 1  (depth 4)
  Ciphertext t3sq = t3 * t3;
  Ciphertext t6 = t3sq + t3sq - one;

  // T7 = 2 T3 T4 - z  (depth 4)
  Ciphertext t3t4 = t3 * t4;
  Ciphertext t7 = t3t4 + t3t4 - z;

  Plaintext c1("c1");
  Plaintext c2("c2");
  Plaintext c3("c3");
  Plaintext c4("c4");
  Plaintext c5("c5");
  Plaintext c6("c6");
  Plaintext c7("c7");
  Plaintext c0("c0");

  Ciphertext term1 = z * c1;
  Ciphertext term2 = t2 * c2;
  Ciphertext term3 = t3 * c3;
  Ciphertext term4 = t4 * c4;
  Ciphertext term5 = t5 * c5;
  Ciphertext term6 = t6 * c6;
  Ciphertext term7 = t7 * c7;

  Ciphertext result = term1 + term2;
  result = result + term3;
  result = result + term4;
  result = result + term5;
  result = result + term6;
  result = result + term7;
  result = result + c0;

  result.set_output("y");
}
```

The failure is a level collision. `term3` and `term4` both land at level 4, but they come from different multiplication histories, so CHEHAB cannot add them. The baseline avoided this by giving every term a distinct level.

My fix is to pad each T_k with ct×`one` so that every term reaches the same depth (4) before its coefficient multiply. Every term then has the same multiplication history, and all sums meet at matching levels. The padding costs about 7 cheap plaintext multiplies, which is small next to the 388 ms baseline.

```cpp
void fhe()
{
  Ciphertext x("x");
  Plaintext alpha("alpha");
  Plaintext one("one");

  // pad: consume n levels by multiplying with the plaintext 1
  auto pad = [&](Ciphertext c, int n) {
    for (int i = 0; i < n; ++i)
      c = c * one;
    return c;
  };

  // z = x/4 in [-1, 1]  (depth 1)
  Ciphertext z = x * alpha;

  // T2 = 2 z^2 - 1  (depth 2)
  Ciphertext z2 = z * z;
  Ciphertext t2 = z2 + z2 - one;

  // T3 = 2 z T2 - z  (depth 3)
  Ciphertext zt2 = z * t2;
  Ciphertext t3 = zt2 + zt2 - z;

  // T4 = 2 T2^2 - 1  (depth 3)
  Ciphertext t2sq = t2 * t2;
  Ciphertext t4 = t2sq + t2sq - one;

  // T5 = 2 T2 T3 - z  (depth 4)
  Ciphertext t2t3 = t2 * t3;
  Ciphertext t5 = t2t3 + t2t3 - z;

  // T6 = 2 T3^2 - 1  (depth 4)
  Ciphertext t3sq = t3 * t3;
  Ciphertext t6 = t3sq + t3sq - one;

  // T7 = 2 T3 T4 - z  (depth 4)
  Ciphertext t3t4 = t3 * t4;
  Ciphertext t7 = t3t4 + t3t4 - z;

  // equalize depths to 4 so all terms share the same multiplication history
  Ciphertext p1 = pad(z, 3);
  Ciphertext p2 = pad(t2, 2);
  Ciphertext p3 = pad(t3, 1);
  Ciphertext p4 = pad(t4, 1);

  Plaintext c0("c0");
  Plaintext c1("c1");
  Plaintext c2("c2");
  Plaintext c3("c3");
  Plaintext c4("c4");
  Plaintext c5("c5");
  Plaintext c6("c6");
  Plaintext c7("c7");

  Ciphertext term1 = p1 * c1;
  Ciphertext term2 = p2 * c2;
  Ciphertext term3 = p3 * c3;
  Ciphertext term4 = p4 * c4;
  Ciphertext term5 = t5 * c5;
  Ciphertext term6 = t6 * c6;
  Ciphertext term7 = t7 * c7;

  Ciphertext result = term1 + term2;
  result = result + term3;
  result = result + term4;
  result = result + term5;
  result = result + term6;
  result = result + term7;
  result = result + c0;

  result.set_output("y");
}
```

The failure is again a same-level collision. This time it happens in the final sum, where two terms at level 5 come from different histories.

I now build the sum as a tree in which every addition joins operands at different levels. Levels are: term1=2, term2=3, term3=4, term4=4, term5=5, term6=5 (padded to 6), term7=5.

- C = term1 + term2 (levels 2, 3 → 3)
- A = term3 + term5 (levels 4, 5 → 5)
- B = term4 + term6 (levels 4, 6 → 6)
- D = A + B (levels 5, 6 → 6)
- E = D + term7 (levels 6, 5 → 6)
- F = E + C (levels 6, 3 → 6), then + c0

Every addition meets different levels, so no scale alignment is needed. The final depth is 6 instead of 8, which also makes the multiplications cheaper.

```cpp
void fhe()
{
  Ciphertext x("x");
  Plaintext alpha("alpha");
  Plaintext one("one");

  // pad: consume n levels by multiplying with the plaintext 1
  auto pad = [&](Ciphertext c, int n) {
    for (int i = 0; i < n; ++i)
      c = c * one;
    return c;
  };

  // z = x/4 in [-1, 1]  (depth 1)
  Ciphertext z = x * alpha;

  // T2 = 2 z^2 - 1  (depth 2)
  Ciphertext z2 = z * z;
  Ciphertext t2 = z2 + z2 - one;

  // T3 = 2 z T2 - z  (depth 3)
  Ciphertext zt2 = z * t2;
  Ciphertext t3 = zt2 + zt2 - z;

  // T4 = 2 T2^2 - 1  (depth 3)
  Ciphertext t2sq = t2 * t2;
  Ciphertext t4 = t2sq + t2sq - one;

  // T5 = 2 T2 T3 - z  (depth 4)
  Ciphertext t2t3 = t2 * t3;
  Ciphertext t5 = t2t3 + t2t3 - z;

  // T6 = 2 T3^2 - 1  (depth 4)
  Ciphertext t3sq = t3 * t3;
  Ciphertext t6 = t3sq + t3sq - one;

  // T7 = 2 T3 T4 - z  (depth 4)
  Ciphertext t3t4 = t3 * t4;
  Ciphertext t7 = t3t4 + t3t4 - z;

  Plaintext c0("c0");
  Plaintext c1("c1");
  Plaintext c2("c2");
  Plaintext c3("c3");
  Plaintext c4("c4");
  Plaintext c5("c5");
  Plaintext c6("c6");
  Plaintext c7("c7");

  // terms: levels 2,3,4,4,5,(6 after pad),5
  Ciphertext term1 = z * c1;
  Ciphertext term2 = t2 * c2;
  Ciphertext term3 = t3 * c3;
  Ciphertext term4 = t4 * c4;
  Ciphertext term5 = t5 * c5;
  Ciphertext term6 = pad(t6, 1) * c6;
  Ciphertext term7 = t7 * c7;

  // tree sum: every addition joins operands at different levels
  Ciphertext C = term1 + term2;      // levels 2,3 -> 3
  Ciphertext A = term3 + term5;      // levels 4,5 -> 5
  Ciphertext B = term4 + term6;      // levels 4,6 -> 6
  Ciphertext D = A + B;              // levels 5,6 -> 6
  Ciphertext E = D + term7;          // levels 6,5 -> 6
  Ciphertext F = E + C;              // levels 6,3 -> 6
  Ciphertext result = F + c0;

  result.set_output("y");
}
```

Attempt 3 is correct but slower (425 ms vs 388 ms). Its main cost is the six ciphertext multiplications, and I can cut that to four.

The identity is T4·T_m = (T_{m+4} + T_{4−m})/2, which gives

p = c0 + (c1−c7)T1 + (c2−c6)T2 + (c3−c5)T3 + T4·(2c5·T1 + 2c6·T2 + 2c7·T3 + c4)

I checked each coefficient against the T5, T6, T7 terms. So only T2, T3 and T4 need ciphertext multiplications (3 of them), and one more multiplies T4 by the inner combination B. That is four ciphertext multiplications, depth 5.

The additions avoid mixed-history collisions: each sum either joins pure products of the same T at the same level, or joins sums at different levels. The "2·" factors are ciphertext self-additions.

```cpp
void fhe()
{
  Ciphertext x("x");
  Plaintext alpha("alpha");
  Plaintext one("one");

  // z = x/4 in [-1, 1]  (depth 1)
  Ciphertext z = x * alpha;

  // T2 = 2 z^2 - 1  (depth 2)
  Ciphertext z2 = z * z;
  Ciphertext t2 = z2 + z2 - one;

  // T3 = 2 z T2 - z  (depth 3)
  Ciphertext zt2 = z * t2;
  Ciphertext t3 = zt2 + zt2 - z;

  // T4 = 2 T2^2 - 1  (depth 3)
  Ciphertext t2sq = t2 * t2;
  Ciphertext t4 = t2sq + t2sq - one;

  Plaintext c0("c0");
  Plaintext c1("c1");
  Plaintext c2("c2");
  Plaintext c3("c3");
  Plaintext c4("c4");
  Plaintext c5("c5");
  Plaintext c6("c6");
  Plaintext c7("c7");

  // inner B = 2c5 T1 + 2c6 T2 + 2c7 T3 + c4   (depth 4)
  Ciphertext z1 = z * c5;
  Ciphertext z1d = z1 + z1;            // level 2
  Ciphertext z2c = t2 * c6;
  Ciphertext z2d = z2c + z2c;          // level 3
  Ciphertext z3 = t3 * c7;
  Ciphertext z3d = z3 + z3;            // level 4
  Ciphertext B = z1d + z2d;            // levels 2,3 -> 3
  B = B + z3d;                         // levels 3,4 -> 4
  B = B + c4;                          // plaintext add

  // product T4 * B  (depth 5)
  Ciphertext prod = t4 * B;

  // outer linear part: (c1-c7) T1 + (c2-c6) T2 + (c3-c5) T3 + c0
  Ciphertext P1 = z * c1;
  Ciphertext Q1 = z * c7;
  Ciphertext P2 = t2 * c2;
  Ciphertext Q2 = t2 * c6;
  Ciphertext P3 = t3 * c3;
  Ciphertext Q3 = t3 * c5;
  Ciphertext D1 = P1 - Q1;             // level 2
  Ciphertext D2 = P2 - Q2;             // level 3
  Ciphertext D3 = P3 - Q3;             // level 4
  Ciphertext O = D1 + D2;              // levels 2,3 -> 3
  O = O + D3;                          // levels 3,4 -> 4
  O = O + c0;                          // plaintext add

  Ciphertext result = prod + O;        // levels 5,4 -> 5
  result.set_output("y");
}
```

Attempt 4 is the best so far at 334.5 ms. I can remove one plaintext multiplication: c6·T2 appears twice (inside the inner product and in the linear part), so I compute it once and reuse it. The same product is subtracted in the linear part and doubled in the inner product. That reduces the plaintext multiplications from 9 to 8, with no change to depth or the ciphertext multiplication count.

```cpp
void fhe()
{
  Ciphertext x("x");
  Plaintext alpha("alpha");
  Plaintext one("one");

  // z = x/4 in [-1, 1]  (depth 1)
  Ciphertext z = x * alpha;

  // T2 = 2 z^2 - 1  (depth 2)
  Ciphertext z2 = z * z;
  Ciphertext t2 = z2 + z2 - one;

  // T3 = 2 z T2 - z  (depth 3)
  Ciphertext zt2 = z * t2;
  Ciphertext t3 = zt2 + zt2 - z;

  // T4 = 2 T2^2 - 1  (depth 3)
  Ciphertext t2sq = t2 * t2;
  Ciphertext t4 = t2sq + t2sq - one;

  Plaintext c0("c0");
  Plaintext c1("c1");
  Plaintext c2("c2");
  Plaintext c3("c3");
  Plaintext c4("c4");
  Plaintext c5("c5");
  Plaintext c6("c6");
  Plaintext c7("c7");

  // shared plaintext products
  Ciphertext u5a = z * c5;     // c5 T1       (level 2)
  Ciphertext u7b = z * c7;     // c7 T1       (level 2)
  Ciphertext u6 = t2 * c6;     // c6 T2       (level 3)
  Ciphertext u5b = t3 * c5;    // c5 T3       (level 4)
  Ciphertext u7a = t3 * c7;    // c7 T3       (level 4)
  Ciphertext p1 = z * c1;      // c1 T1       (level 2)
  Ciphertext p2 = t2 * c2;     // c2 T2       (level 3)
  Ciphertext p3 = t3 * c3;     // c3 T3       (level 4)

  // inner B = 2c5 T1 + 2c6 T2 + 2c7 T3 + c4   (depth 4)
  Ciphertext d5 = u5a + u5a;
  Ciphertext d6 = u6 + u6;
  Ciphertext d7 = u7a + u7a;
  Ciphertext B = d5 + d6;      // levels 2,3 -> 3
  B = B + d7;                  // levels 3,4 -> 4
  B = B + c4;                  // plaintext add

  // product T4 * B  (depth 5)
  Ciphertext prod = t4 * B;

  // linear part: (c1-c7) T1 + (c2-c6) T2 + (c3-c5) T3 + c0
  Ciphertext D1 = p1 - u7b;    // level 2
  Ciphertext D2 = p2 - u6;     // level 3
  Ciphertext D3 = p3 - u5b;    // level 4
  Ciphertext O = D1 + D2;      // levels 2,3 -> 3
  O = O + D3;                  // levels 3,4 -> 4
  O = O + c0;                  // plaintext add

  Ciphertext result = prod + O;   // levels 5,4 -> 5
  result.set_output("y");
}
```

Attempt 5 was slower (407 ms vs 334.5 ms) and its operation counts match attempt 4 exactly, so the shared-product rewrite changed nothing structurally; CHEHAB's common-subexpression elimination was already merging those products. The timing gap is likely noise or ordering effects. I'm returning the attempt 4 kernel, the fastest correct version so far.

